	private readonly Dictionary<string, TaskCompletionSource<PromptResponse>> _pendingPrompts = new();

	// --- Session startup ---

	/// <summary>
	/// Loads the game definition and card sets from the generated JSON files,
	/// then starts the game session.
	/// </summary>
	/// <param name="hostManifestData">Session-specific overrides; pass an empty
	/// <c>Dictionary</c> if none are needed.</param>
	/// <param name="definitionPath">Resource path to <c>game_definition.json</c>.</param>
	/// <param name="cardSetPaths">Array of resource paths to card-set JSON files.</param>
	public void StartGame(
		Godot.Collections.Dictionary hostManifestData,
		string definitionPath = "res://archetype/game_definition.json",
		Godot.Collections.Array? cardSetPaths = null)
	{
		var jsonOptions = GameDefinitionJsonOptions.Build();
		var defJson = FileAccess.GetFileAsString(definitionPath);
		var definition = JsonSerializer.Deserialize<GameDefinition>(defJson, jsonOptions)!;

		var cardSets = new List<CardSet>();
		var paths = (cardSetPaths == null || cardSetPaths.Count == 0) ? LoadDefaultCardSetPaths() : cardSetPaths;
		foreach (var path in paths)
		{
			var json = FileAccess.GetFileAsString(path.ToString()!);
			var set = JsonSerializer.Deserialize<CardSet>(json, jsonOptions);
			if (set != null) cardSets.Add(set);
		}
		definition = definition.WithCardSets(cardSets);

		_cts = new CancellationTokenSource();
		var builder = GameSession.Create(definition)
			.WithRandomSource(new Archetype.Engine.SeededRandom(GD.Randi()));

		builder = builder.WithPlayerStrategy("alice", new InnerStrategy("alice", this));
		builder = builder.WithPlayerStrategy("bob", new InnerStrategy("bob", this));

		var session = builder.Build();
		_runTask = RunLoopAsync(session, _cts.Token);
	}

	private static Godot.Collections.Array LoadDefaultCardSetPaths()
	{
		var result = new Godot.Collections.Array();
		var dir = DirAccess.Open("res://archetype/card-sets/");
		if (dir == null) return result;
		foreach (var file in dir.GetFiles())
			if (file.EndsWith(".json"))
				result.Add($"res://archetype/card-sets/{file}");
		return result;
	}

	private async Task RunLoopAsync(GameSession session, CancellationToken ct)
	{
		try
		{
			var result = await session.RunAsync(ct);
			// winnerName is empty string for a draw (D33 spec).
			EmitSignal(SignalName.GameOver, result.Winner ?? string.Empty);
		}
		catch (System.OperationCanceledException)
		{
			// Normal shutdown: node exited tree while game was running.
		}
		catch (System.Exception ex)
		{
			GD.PrintErr("[ArchetypeNode] engine error: ", ex.Message, "\n", ex.StackTrace);
			EmitSignal(SignalName.GameError, ex.Message);
		}
	}

	/// <summary>Cancels the game loop when the node leaves the scene tree.</summary>
	public override void _ExitTree()
	{
		_cts?.Cancel();
		_cts?.Dispose();
		_cts = null;
