		var choices = DictionaryToStringObject(costChoices);
		tcs.TrySetResult(new PlayCard(new AtomId(cardAtomId), choices));
	}

	/// <summary>Submits an activate-ability action for the named player.</summary>
	public void SubmitActivateAbility(string playerName, long sourceAtomId, string effectName, Godot.Collections.Dictionary costChoices)
	{
		if (!_pendingActions.TryGetValue(playerName, out var tcs)) return;
		var choices = DictionaryToStringObject(costChoices);
		tcs.TrySetResult(new ActivateAbility(new AtomId(sourceAtomId), effectName, choices));
	}

	/// <summary>Submits a pass action for the named player.</summary>
	public void SubmitPass(string playerName)
	{
		if (!_pendingActions.TryGetValue(playerName, out var tcs)) return;
		tcs.TrySetResult(new Pass());
	}

	/// <summary>Submits a prompt response for the named player.</summary>
	public void SubmitPromptResponse(string playerName, Godot.Collections.Dictionary response)
	{
		if (!_pendingPrompts.TryGetValue(playerName, out var tcs)) return;
		var chosen = new System.Collections.Generic.List<object>();
		foreach (var key in response.Keys)
			chosen.Add(response[key]);
		tcs.TrySetResult(new ChoiceResponse(chosen));
	}

	// --- Post-action signal emission ---

	/// <summary>
	/// Iterates <paramref name="events"/> (depth-first) and emits a hardcoded
	/// GDScript signal for every event whose keyword name is in the derived set.
	/// </summary>
	private void EmitDerivedSignals(System.Collections.Generic.IReadOnlyList<GameEvent> events)
	{
		foreach (var root in events)
		foreach (var ev in root.SelfAndDescendants())
		{
			switch (ev.KeywordName)
			{
				case "heal":
					EmitSignal(SignalName.OnHeal
						, (long)(AtomId)(ev.BoundArgs["target"])
						, (double)(ev.BoundArgs["amount"])
					);
					break;
				case "strike":
					EmitSignal(SignalName.OnStrike
						, (long)(AtomId)(ev.BoundArgs["target"])
						, (double)(ev.BoundArgs["power"])
					);
					break;
			}
		}
	}

	private static System.Collections.Generic.Dictionary<string, object> DictionaryToStringObject(
		Godot.Collections.Dictionary dict)
	{
		var result = new System.Collections.Generic.Dictionary<string, object>(StringComparer.Ordinal);
		foreach (var key in dict.Keys)
			result[key.ToString()!] = dict[key];
		return result;
	}

