	// --- InnerStrategy — per-player IPlayerStrategy implementation ---

	private sealed class InnerStrategy : IPlayerStrategy
	{
		private readonly string _playerName;
		private readonly ArchetypeNode _node;

		public InnerStrategy(string playerName, ArchetypeNode node)
		{
			_playerName = playerName;
			_node = node;
		}

		public async Task<PlayerAction?> SelectActionAsync(
			AvailableActions available,
			GameStateView state,
			CancellationToken ct = default)
		{
			// Emit derived signals for the just-completed action before opening
			// the next decision window.  LastActionEvents is populated by the
			// engine after all blocks, SBRs, and triggers resolve (D30).
