			var tcs = new TaskCompletionSource<PlayerAction?>(
				TaskCreationOptions.RunContinuationsAsynchronously);
			_node._pendingActions[_playerName] = tcs;
			_node._stateView = state;
			_node.EmitSignal(SignalName.ActionRequested, _playerName, availableDict);

			using var reg = ct.Register(() => tcs.TrySetCanceled());
			return await tcs.Task;
		}

		public async Task<PromptResponse> RespondToPromptAsync(
			PromptContext context,
			GameStateView state,
			CancellationToken ct = default)
