			var contextDict = new Godot.Collections.Dictionary();
			var tcs = new TaskCompletionSource<PromptResponse>(
				TaskCreationOptions.RunContinuationsAsynchronously);
			_node._pendingPrompts[_playerName] = tcs;
			_node._stateView = state;
			_node.EmitSignal(SignalName.PromptRequested, _playerName, promptType, contextDict);

			using var reg = ct.Register(() => tcs.TrySetCanceled());
			return await tcs.Task;
		}

		private static Godot.Collections.Dictionary SerialiseAvailableActions(AvailableActions available)
		{
			var dict = new Godot.Collections.Dictionary();
			var cards = new Godot.Collections.Array();
			foreach (var opt in available.PlayableCards)
				cards.Add((long)opt.Card);
			dict["playable_cards"] = cards;
			var abilities = new Godot.Collections.Array();
			foreach (var opt in available.ActivatableAbilities)
			{
				var entry = new Godot.Collections.Dictionary();
				entry["source"] = (long)opt.Source;
				entry["effect_name"] = opt.EffectName;
				abilities.Add(entry);
			}
			dict["activatable_abilities"] = abilities;
			dict["can_pass"] = available.CanPass;
			return dict;
		}
	}

